TRIGGERED_ABILITY.RESOLUTION_TIME_ACTION:
if MTG():GetNumberOfStartingPlayers() > 2 then -- there is an actual choice so time to decide which oppoenent local filter = ClearFilter() filter:SetFilterType( FILTER_TYPE_PLAYERS ) filter:Add( FE_TEAM, OP_NOT, EffectController():GetTeam() ) EffectController():ChooseItem( "CARD_QUERY_CHOOSE_PLAYER_TO_SOLDIER", EffectDC():Make_Targets(0) )
else -- we are only in a two player duel so we just grab the first oppoenent as we only have one for i = 0, (MTG():GetNumberOfPlayers()-1) do local player = MTG():GetNthPlayer(i)
if player ~= nil and player ~= EffectController() then EffectDC():Make_Targets(0):Set_PlayerPtr(0, player) end end end
